/** Codes the server sends as { error: { code, detailsForLog } }. The web client adds its own SERVER_UNREACHABLE. */
export type ErrorCode =
  | 'CLAUDE_NOT_INSTALLED'
  | 'CLAUDE_NOT_LOGGED_IN'
  | 'LLM_TIMEOUT'
  | 'LLM_BAD_OUTPUT'
  | 'LLM_FAILED'
  | 'LLM_CANCELLED'
  | 'DATA_WRITE_FAILED'
  | 'FILE_TOO_LARGE'
  | 'FILE_TYPE_NOT_ALLOWED'
  | 'TOO_MANY_FILES'
  | 'CV_UNREADABLE'
  | 'PROFILE_NOT_READY'
  | 'SOURCE_UNAVAILABLE'
  | 'SOURCE_RATE_LIMITED'
  | 'SOURCE_CHANGED'
  | 'SEARCH_ALREADY_RUNNING'
  | 'WISHES_INCOMPLETE'
  | 'NOT_A_VACANCY'
  | 'VACANCY_DUPLICATE'
  | 'VACANCY_NOT_FOUND'
  | 'BROWSER_MISSING'
  | 'LETTER_TOO_LONG'
  | 'PACKAGE_RULES_BROKEN'
  | 'PACKAGE_EXISTS'
  | 'MAIL_NOT_CONFIGURED'
  | 'MAIL_AUTH'
  | 'MAIL_CONNECT'
  | 'MAIL_REJECTED'
  | 'CONFLICT'
  | 'BAD_REQUEST'
  | 'NOT_FOUND'
  | 'UNKNOWN';

/**
 * Ids of the translated, person-facing sentences an error may carry (`errors.reasons.<reason>` in the web locales).
 * One list for server and web, so a typo in either is a compile error.
 */
export type ErrorReason =
  | 'cvTooLittleText'
  | 'cvNoContent'
  | 'cvDocxBroken'
  | 'fileTypeDetected'
  | 'tooManyDocuments'
  | 'profileMissing'
  | 'llmTimeout'
  | 'cancelledByUser'
  | 'proposalChanged'
  | 'pastedTooShort'
  | 'offerGone'
  | 'noStory'
  | 'attachmentUnreadable'
  | 'packageBusy'
  | 'packageSent'
  | 'packageSending'
  | 'packageChanged';
